    "instruction": "读 100–130 词短文，选一个正确答案。",
    "content": "During deep sleep, the brain replays what you learned during the day and moves it into long-term memory. Students who sleep for seven to eight hours before an exam remember more than those who stay up late. Researchers also note that sleep affects mood, attention and the immune system. A regular routine helps the brain prepare for sleep, while caffeine and screens can delay it. Students who sacrifice sleep to study may perform worse the next day. Schools should teach sleep habits alongside revision skills. The evidence should inform policy. Schools and families should treat sleep as part of learning, not as optional.",
    "question": "According to the passage, why is sleep important for learning?",
