    "instruction": "读 100–130 词短文，选 2 个正确答案。错选倒扣 1 分。",
    "content": "Remote work has changed how companies hire. Employers can now recruit from a wider pool of candidates, and staff save time on commuting. However, remote employees often report feeling isolated, and some managers find it harder to build team spirit. Some companies have reduced office space, while others have invested in collaboration hubs. Junior staff may miss informal mentoring, and managers must create deliberate opportunities for connection. The effect on city centres depends on how many days employees attend. Long-term studies are still limited, so policy should remain flexible. The balance between freedom and connection is the key challenge. The evidence should inform policy.",
    "question": "Which two statements are true according to the passage?",
