    "instruction": "读情景，20 秒准备，40 秒作答。用“回应—说明—理由/安排—收尾”。",
    "explanation": "RTS 考“合不合适”，不是考观点深度。四步框架能覆盖内容分。",
    "tip": "不要背 DI 模板；一开口就要像在跟人说话。",
    "content": "The book you need for an assignment is already borrowed from the library. The assignment is due in three days. Ask the librarian for another option and explain your deadline.",
