    "title": "噪音",
    "instruction": "读 100–130 词短文，选一个正确答案。",
    "explanation": "文中说居民欢迎、建筑商认为成本增加，推断“有益健康但有反对”。",
    "tip": "出现 However 的段落，主旨通常在转折后；选项太绝对的先排除。",
    "content": "Noise from traffic and construction is often seen as an unavoidable part of city life. Yet research links long-term exposure to sleep problems and heart disease. Some cities have introduced quiet zones and stricter rules for night work. These measures are popular with residents, although builders argue that they increase costs. Builders argue that night-time restrictions increase costs and delay projects. Residents, however, point to the health risks of disrupted sleep. Some cities now require noise assessments before construction begins and publish the results. Compensation for affected households is also being discussed. The debate balances economic activity against public health.",
    "question": "What can be inferred about noise rules?",
