    "content": "A third of the food produced for human consumption is wasted. In wealthy countries, much of this waste happens in shops and homes, where food is thrown away after passing a label date. In poorer countries, waste often occurs after harvest because storage is inadequate. Solutions therefore need to differ by region. Households can reduce waste by planning meals and storing food correctly. Retailers can relax cosmetic standards for fruit and vegetables. Food-sharing apps can redistribute surplus meals. However, prevention is better than recycling, because it avoids the resources used to grow and transport food in the first place. Measurement is essential for tracking progress.",
