    "tip": "出现 However 的段落，主旨通常在转折后；选项太绝对的先排除。",
    "content": "Many museums now offer free entry to attract wider audiences. Free admission can increase visitor numbers and make culture more accessible. However, museums still need income for conservation and staff, so some rely on donations or charge for special exhibitions. The debate is therefore about who should pay, not whether culture matters. Free entry can also increase visitor numbers, but it does not cover conservation costs. Some museums rely on donations, sponsorships or charges for special exhibitions. Critics warn that this can create a two-tier system, where permanent collections are free but the best shows are expensive. Transparency about funding is essential.",
