    "title": "公共交通",
    "instruction": "读 100–130 词短文，选 2 个正确答案。错选倒扣 1 分。",
    "explanation": "A 对应 reduces air pollution；B 对应 must be frequent and reliable；C、D 与原文相反。",
    "tip": "多选是阅读里唯一倒扣的题：写不出“原文哪一句支持”，就不要选。",
    "content": "Cities that invest in buses and trains can move more people with less road space. Good public transport also reduces air pollution and gives low-income residents access to jobs. However, services must be frequent and reliable, or passengers return to their cars. Fare levels matter too: if tickets are too expensive, the poorest travellers are excluded. Fare integration across buses and trains can also make travel simpler. However, public transport competes with cars for road space, so cities may need bus lanes and congestion charges. Without reliable funding, services can deteriorate and passengers are lost. Long-term planning matters more than isolated projects.",
    "question": "Which two statements are supported by the passage?",
