    "content": "University libraries are changing. Many now provide group study rooms, digital databases and support for online students. Some have reduced their printed collections to make space for collaborative work. However, students still value quiet individual study areas, and researchers need access to specialist archives. Libraries therefore have to serve several groups at once. Some libraries have moved rarely used books to storage and share specialist collections with other institutions. This frees space for teaching and group work, but it can delay access for researchers. Balancing immediate needs against long-term preservation is difficult. User surveys and usage data can help, although no single design suits every campus.",
